#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        vector<int> np;
        for(int i = n-y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n-y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x, y});
    };

    for(int i = 0; i < n-1; i++){
        // Find position of element i+1
        int j = -1;
        for(int k = i; k < n; k++) if(p[k] == i+1){ j = k; break; }
        if(j == i) continue;

        // Step 1: move element from position j to position 0
        if(j > 0){
            // x=1, y=n-j: C=[j..n-1], B=[1..j-1], A=[0] -> C B A
            // element at j goes to position 0
            apply_op(1, n-j);
        }
        // Now element i+1 is at position 0

        // Step 2: move element from position 0 to position i
        if(i > 0){
            // x=n-i, y=i: C=[n-i..n-1], B=empty(if x+y=n), A=[0..n-i-1]
            // Result: C, A = [n-i..n-1, 0..n-i-1], element at 0 goes to position i
            apply_op(n-i, i);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto& [a,b] : ops) printf("%d %d\n", a, b);
}
